import {createChatOrchestrator} from './chatOrchestrator.js';
import {answering, writeSignalPromptBuilder} from '../infrastructure/writeSignalTestSupport.js';
import type {ChatSession} from '../types/session.js';

const SENT_AT = '2026-01-01T00:00:00.000Z';

const initialSession = (): ChatSession => ({
  sessionId: 's1',
  userId: 'u1',
  entries: [{role: 'user', content: 'hello', timestamp: SENT_AT}],
});

describe('beforeSession throwing', () => {
  it('runs onError and afterSession when beforeSession throws', async () => {
    const errorToThrow = new Error('Database connection failed in beforeSession');
    let caughtError: Error | undefined;
    let afterSessionRan = false;

    const orchestrator = createChatOrchestrator(answering('hello back'), writeSignalPromptBuilder, undefined, {
      hooks: {
        beforeSession: async () => {
          throw errorToThrow;
        },
        onError: async (_session, error) => {
          caughtError = error;
        },
        afterSession: async () => {
          afterSessionRan = true;
        },
      },
    });

    const outcome = await orchestrator
      .processMessage(initialSession())
      .catch((error: Error) => `rejected: ${error.message}`);

    expect({outcome, caughtError, afterSessionRan}).toEqual({
      outcome: 'rejected: Database connection failed in beforeSession',
      caughtError: errorToThrow,
      afterSessionRan: true,
    });
  });
});
